import 'package:flutter/material.dart';import '../auth/auth_service.dart';import '../wallet/topup_screen.dart';import '../products/product_upload_screen.dart';import '../admin/admin_guard.dart';import '../marketplace/marketplace_screen.dart';import '../chat/chat_inbox_screen.dart';class HomeScreen extends StatelessWidget{const HomeScreen({super.key});@override Widget build(BuildContext c)=>DefaultTabController(length:2,child:Scaffold(appBar:AppBar(title:const Text('Flowa'),actions:[IconButton(icon:const Icon(Icons.account_balance_wallet_outlined),onPressed:()=>Navigator.push(c,MaterialPageRoute(builder:(_)=>const TopUpScreen()))),PopupMenuButton<String>(onSelected:(v){if(v=='admin')Navigator.push(c,MaterialPageRoute(builder:(_)=>const AdminGuard()));if(v=='logout')AuthService().logout();},itemBuilder:(_)=>const [PopupMenuItem(value:'admin',child:Text('Admin Dashboard')),PopupMenuItem(value:'logout',child:Text('Keluar'))])],bottom:const TabBar(tabs:[Tab(icon:Icon(Icons.storefront_outlined),text:'Iklan'),Tab(icon:Icon(Icons.chat_bubble_outline),text:'Chat')])),body:const TabBarView(children:[MarketplaceScreen(),ChatInboxScreen()]),floatingActionButton:FloatingActionButton.extended(onPressed:()=>Navigator.push(c,MaterialPageRoute(builder:(_)=>const ProductUploadScreen())),icon:const Icon(Icons.add),label:const Text('Pasang Iklan'))));}